// Due for attempt?: pass one item when the claimer may try now: not claimed, not stopped, and the wait since the last attempt has passed.
const data = $getWorkflowStaticData('global');
if (data.claimed || data.stopped || Date.now() < (data.nextAttemptAt ?? 0)) return [];
// Hold the claimer while this attempt runs, so a run that starts meanwhile cannot launch a second instance.
data.nextAttemptAt = Date.now() + 15 * 60 * 1000;
return [{ json: { due: true } }];

// Cost guard: count the A1 instances and the boot and block volumes that exist, and refuse the launch unless the request still fits the Always Free limits.
// A list request that fails, or runs past MAX_PAGES, is a refusal too: an unknown total is not a free total.
const crypto = require('crypto');
const helpers = this.helpers;

const LIMIT_OCPUS = 4;
const LIMIT_MEMORY_GB = 24;
const LIMIT_STORAGE_GB = 200;
const MAX_PAGES = 100;
const REQUEST = { shape: 'VM.Standard.A1.Flex', ocpus: 4, memoryInGBs: 24, bootVolumeSizeInGBs: 50, displayName: 'vm-hunter-a1' };

const base = $env.HUNTER_OCI_API_BASE;
const host = new URL(base).host;
const keyId = [$env.HUNTER_OCI_TENANCY_OCID, $env.HUNTER_OCI_USER_OCID, $env.HUNTER_OCI_KEY_FINGERPRINT].join('/');
// The PEM may arrive with literal \n sequences when it is set as one line in the environment.
const key = $env.HUNTER_OCI_PRIVATE_KEY_PEM.replace(/\\n/g, '\n');
const compartment = encodeURIComponent($env.HUNTER_OCI_COMPARTMENT_OCID);
const domain = encodeURIComponent($env.HUNTER_OCI_AVAILABILITY_DOMAIN);

// Signed GET (OCI HTTP signatures): the signing string covers the request target, the date and the host.
function signedGet(target) {
  const date = new Date().toUTCString();
  const signing = [`(request-target): get ${target}`, `date: ${date}`, `host: ${host}`].join('\n');
  const signature = crypto.sign('sha256', Buffer.from(signing), key).toString('base64');
  return { date, authorization: `Signature version="1",keyId="${keyId}",algorithm="rsa-sha256",headers="(request-target) date host",signature="${signature}"` };
}

// Every page of one list request, as one array. Throws on any failure.
async function listAll(path) {
  const items = [];
  let page = '';
  for (let pages = 0; pages < MAX_PAGES; pages++) {
    const target = page ? `${path}&page=${encodeURIComponent(page)}` : path;
    const response = await helpers.httpRequest({ method: 'GET', url: base + target, headers: signedGet(target), returnFullResponse: true, ignoreHttpStatusErrors: true });
    if (response.statusCode !== 200) throw new Error(`${path.split('?')[0]} returned HTTP ${response.statusCode}`);
    const list = typeof response.body === 'string' ? JSON.parse(response.body) : response.body;
    items.push(...list);
    page = response.headers['opc-next-page'] ?? '';
    if (!page) return items;
  }
  throw new Error(`${path.split('?')[0]} has more than ${MAX_PAGES} pages`);
}

const data = $getWorkflowStaticData('global');
const metrics = data.metrics ?? { counters: {}, alerted: {} };
const problems = [];
let used = '';
try {
  const instances = await listAll(`/20160918/instances?compartmentId=${compartment}`);
  const bootVolumes = await listAll(`/20160918/bootVolumes?compartmentId=${compartment}&availabilityDomain=${domain}`);
  const blockVolumes = await listAll(`/20160918/volumes?compartmentId=${compartment}`);

  const a1 = instances.filter((i) => i.shape === REQUEST.shape && i.lifecycleState !== 'TERMINATED');
  const usedOcpus = a1.reduce((sum, i) => sum + (i.shapeConfig?.ocpus ?? 0), 0);
  const usedMemory = a1.reduce((sum, i) => sum + (i.shapeConfig?.memoryInGBs ?? 0), 0);
  const usedStorage = [...bootVolumes, ...blockVolumes]
    .filter((v) => !['TERMINATED', 'TERMINATING'].includes(v.lifecycleState))
    .reduce((sum, v) => sum + (v.sizeInGBs ?? 0), 0);
  used = `Existing: ${usedOcpus} OCPU, ${usedMemory} GB memory, ${usedStorage} GB storage.`;

  if (REQUEST.shape !== 'VM.Standard.A1.Flex') problems.push(`shape ${REQUEST.shape} is not free`);
  if (usedOcpus + REQUEST.ocpus > LIMIT_OCPUS) problems.push(`OCPUs would be ${usedOcpus + REQUEST.ocpus}, the limit is ${LIMIT_OCPUS}`);
  if (usedMemory + REQUEST.memoryInGBs > LIMIT_MEMORY_GB) problems.push(`memory would be ${usedMemory + REQUEST.memoryInGBs} GB, the limit is ${LIMIT_MEMORY_GB} GB`);
  if (usedStorage + REQUEST.bootVolumeSizeInGBs > LIMIT_STORAGE_GB) problems.push(`storage would be ${usedStorage + REQUEST.bootVolumeSizeInGBs} GB, the limit is ${LIMIT_STORAGE_GB} GB`);
} catch (error) {
  problems.push(`could not list existing resources: ${error.message}`);
}

if (problems.length) {
  // A refusal stops the claimer until its static data is reset; it is never retried.
  data.stopped = true;
  const counters = metrics.counters ?? {};
  counters.costGuardRefusals = (counters.costGuardRefusals ?? 0) + 1;
  data.metrics = { ...metrics, counters };
  return [{ json: { kind: 'failure', title: 'Cost guard refused the A1 launch', body: [...problems, used, 'The claimer has stopped.'].filter(Boolean).join('\n'), url: '' } }];
}
return [{ json: { kind: '', title: '', body: '', url: '', request: REQUEST } }];

// Launch instance: sign the launch request and send it. Runs only after the cost guard let it through.
const crypto = require('crypto');
const { request } = $input.first().json;
const base = $env.HUNTER_OCI_API_BASE;
const target = '/20160918/instances';
const host = new URL(base).host;
const keyId = [$env.HUNTER_OCI_TENANCY_OCID, $env.HUNTER_OCI_USER_OCID, $env.HUNTER_OCI_KEY_FINGERPRINT].join('/');
const key = $env.HUNTER_OCI_PRIVATE_KEY_PEM.replace(/\\n/g, '\n');

const body = JSON.stringify({
  availabilityDomain: $env.HUNTER_OCI_AVAILABILITY_DOMAIN,
  compartmentId: $env.HUNTER_OCI_COMPARTMENT_OCID,
  displayName: request.displayName,
  shape: request.shape,
  shapeConfig: { ocpus: request.ocpus, memoryInGBs: request.memoryInGBs },
  sourceDetails: { sourceType: 'image', imageId: $env.HUNTER_OCI_IMAGE_OCID, bootVolumeSizeInGBs: request.bootVolumeSizeInGBs },
  createVnicDetails: { subnetId: $env.HUNTER_OCI_SUBNET_OCID, assignPublicIp: true },
  metadata: { ssh_authorized_keys: $env.HUNTER_OCI_SSH_PUBLIC_KEY },
});
const date = new Date().toUTCString();
const digest = crypto.createHash('sha256').update(body).digest('base64');
const contentType = 'application/json';
const contentLength = String(Buffer.byteLength(body));
const signing = [
  `(request-target): post ${target}`,
  `date: ${date}`,
  `host: ${host}`,
  `x-content-sha256: ${digest}`,
  `content-type: ${contentType}`,
  `content-length: ${contentLength}`,
].join('\n');
const signature = crypto.sign('sha256', Buffer.from(signing), key).toString('base64');

const response = await this.helpers.httpRequest({
  method: 'POST',
  url: base + target,
  headers: {
    date,
    'x-content-sha256': digest,
    'content-type': contentType,
    'content-length': contentLength,
    authorization: `Signature version="1",keyId="${keyId}",algorithm="rsa-sha256",headers="(request-target) date host x-content-sha256 content-type content-length",signature="${signature}"`,
  },
  body,
  returnFullResponse: true,
  ignoreHttpStatusErrors: true,
});
let responseBody = response.body;
try {
  if (typeof responseBody === 'string') responseBody = JSON.parse(responseBody);
} catch {
  // Keep the raw text when the body is not JSON.
}
return [{ json: { statusCode: response.statusCode, headers: response.headers, body: responseBody } }];

// Read response: classify one launch response, update the claimer's counters and the wait before the next attempt, and pass on the message to send (if any).
const { statusCode, headers = {}, body = {} } = $input.first().json;
const data = $getWorkflowStaticData('global');
const metrics = data.metrics ?? { counters: {}, alerted: {} };
const counters = metrics.counters ?? {};
const today = new Intl.DateTimeFormat('en-CA', { timeZone: $env.GENERIC_TIMEZONE || 'UTC', year: 'numeric', month: '2-digit', day: '2-digit' }).format(new Date());
const message = typeof body === 'object' && body ? body.message ?? '' : '';
const requestId = headers['opc-request-id'] ?? '';
counters.attempts = (counters.attempts ?? 0) + 1;

let outcome = 'error';
let wait = 60;
let consecutive429 = 0;
let notice = { kind: '', title: '', body: '', url: '' };

if (statusCode === 200 && body.id) {
  outcome = 'claimed';
  counters.success = (counters.success ?? 0) + 1;
  data.claimed = { id: body.id, claimedAt: new Date().toISOString() };
  notice = { kind: 'claim', title: `A1 VM created: ${body.displayName}`, body: `Instance ${body.id}\n${body.shape}, ${body.shapeConfig?.ocpus} OCPU, ${body.shapeConfig?.memoryInGBs} GB\nAttempts: ${counters.attempts}`, url: '' };
} else if (statusCode === 500 && message.includes('Out of host capacity')) {
  outcome = 'capacity';
  counters.outOfCapacity = (counters.outOfCapacity ?? 0) + 1;
} else if (statusCode === 429) {
  outcome = 'throttled';
  counters.rateLimited = (counters.rateLimited ?? 0) + 1;
  consecutive429 = (metrics.consecutive429 ?? 0) + 1;
  // Doubles from 60 seconds, capped at 15 minutes; a longer Retry-After from Oracle is honoured within the cap.
  const retryAfter = Number(headers['retry-after']) || 0;
  wait = Math.min(900, Math.max(60 * 2 ** (consecutive429 - 1), retryAfter));
  if (wait === 900 && metrics.alerted?.capReached !== today) {
    metrics.alerted = { ...(metrics.alerted ?? {}), capReached: today };
    notice = { kind: 'alert', title: 'A1 claim at the 15-minute rate-limit wait', body: `Rate limited (HTTP 429) on ${consecutive429} attempts in a row. The claimer keeps trying every 15 minutes.`, url: '' };
  }
} else if ([400, 401, 404].includes(statusCode)) {
  // Configuration problem: retrying cannot fix it, so the claimer stops until its configuration is fixed.
  outcome = 'config';
  counters.configErrors = (counters.configErrors ?? 0) + 1;
  data.stopped = true;
  notice = { kind: 'failure', title: `A1 claim stopped: HTTP ${statusCode}`, body: `${body.code ?? 'unknown'}: ${message}\nRequest id: ${requestId}\nThe claimer will not retry until its configuration is fixed.`, url: '' };
} else {
  counters.errors = (counters.errors ?? 0) + 1;
}

metrics.counters = counters;
metrics.day = metrics.day ?? today;
metrics.consecutive429 = consecutive429;
metrics.currentWaitSeconds = wait;
data.metrics = metrics;
data.nextAttemptAt = Date.now() + wait * 1000;
return [{ json: { outcome, ...notice } }];

// Shape summary: build the 09:00 claimer summary line from the counters, then reset the counters for the new local day.
const today = new Intl.DateTimeFormat('en-CA', { timeZone: $env.GENERIC_TIMEZONE || 'UTC', year: 'numeric', month: '2-digit', day: '2-digit' }).format(new Date());
const data = $getWorkflowStaticData('global');
const metrics = data.metrics ?? { counters: {}, alerted: {} };
const c = metrics.counters ?? {};
const state = data.claimed ? 'claimed' : data.stopped ? 'stopped' : 'hunting';
const line = `Claimer · ${c.attempts ?? 0} attempts · ${c.outOfCapacity ?? 0} out of capacity · ${c.rateLimited ?? 0} rate limited · ${c.errors ?? 0} errors · ${c.costGuardRefusals ?? 0} cost guard refusals · ${state}`;
data.metrics = { day: today, counters: {}, alerted: metrics.alerted ?? {} };
return [{ json: { kind: 'summary', title: `Claimer summary (${metrics.day ?? today})`, body: line, url: '' } }];
